{
  "units": [
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section heading for 14 CFR § 61.56 Flight review, conveying no substantive legal requirement."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Except as provided in paragraphs (b) and (f) of § 61.56, a flight review consists of a minimum of 1 hour of flight training and 1 hour of ground training."
    },
    {
      "quote_ref": "F003",
      "scope_refs": ["F002"],
      "kind": "requirement",
      "meaning": "Except as otherwise provided in § 61.56, a flight review must include a review of the current general operating and flight rules of 14 CFR part 91."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F002"],
      "kind": "requirement",
      "meaning": "Except as otherwise provided in § 61.56, a flight review must include a review of those maneuvers and procedures that, at the discretion of the person giving the review, are necessary for the pilot to demonstrate the safe exercise of the privileges of the pilot certificate."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F002"],
      "kind": "alternative",
      "meaning": "Glider pilots may substitute a minimum of three instructional flights in a glider, each of which includes a flight to traffic pattern altitude, in lieu of the 1 hour of flight training required in paragraph (a) of § 61.56."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F006"],
      "kind": "prohibition",
      "meaning": "Except as provided in paragraphs (d), (e), and (g) of § 61.56, no person may act as pilot in command of an aircraft unless, since the beginning of the 24th calendar month before the month in which that pilot acts as pilot in command, that person has accomplished a flight review given in an aircraft for which that pilot is rated by an authorized instructor."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F006"],
      "kind": "prohibition",
      "meaning": "Except as provided in paragraphs (d), (e), and (g) of § 61.56, no person may act as pilot in command of an aircraft unless, since the beginning of the 24th calendar month before the month in which that pilot acts as pilot in command, that person has a logbook endorsed from an authorized instructor who gave the review certifying that the person has satisfactorily completed the review."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F006", "F009"],
      "kind": "exemption",
      "meaning": "A person who has, since the beginning of the 24th calendar month before the month in which that pilot acts as pilot in command, passed a pilot proficiency check or practical test conducted by an examiner, an approved pilot check airman, or a U.S. Armed Force, for a pilot certificate, rating, or operating privilege, need not accomplish the flight review required by § 61.56."
    },
    {
      "quote_ref": "F012",
      "scope_refs": ["F006", "F009", "F011"],
      "kind": "exemption",
      "meaning": "A person who has, since the beginning of the 24th calendar month before the month in which that pilot acts as pilot in command, passed a practical test conducted by an examiner for the issuance of a flight instructor certificate need not accomplish the flight review required by § 61.56."
    },
    {
      "quote_ref": "F013",
      "scope_refs": ["F006", "F009", "F011"],
      "kind": "exemption",
      "meaning": "A person who has, since the beginning of the 24th calendar month before the month in which that pilot acts as pilot in command, passed a practical test conducted by an examiner for an additional rating on a flight instructor certificate need not accomplish the flight review required by § 61.56."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F006", "F009", "F011"],
      "kind": "exemption",
      "meaning": "A person who has, since the beginning of the 24th calendar month before the month in which that pilot acts as pilot in command, passed a practical test conducted by an examiner to meet the recent experience requirements for a flight instructor certificate in accordance with § 61.197(b)(1) need not accomplish the flight review required by § 61.56."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F006", "F009", "F011"],
      "kind": "exemption",
      "meaning": "A person who has, since the beginning of the 24th calendar month before the month in which that pilot acts as pilot in command, passed a practical test conducted by an examiner for the reinstatement of flight instructor privileges in accordance with § 61.199(b)(2) need not accomplish the flight review required by § 61.56."
    },
    {
      "quote_ref": "F016",
      "scope_refs": ["F006"],
      "kind": "exemption",
      "meaning": "A person who has, since the beginning of the 24th calendar month before the month in which that pilot acts as pilot in command, satisfactorily accomplished one or more phases of an FAA-sponsored pilot proficiency program need not accomplish the flight review required by § 61.56."
    },
    {
      "quote_ref": "F018",
      "scope_refs": ["F002", "F006", "F017"],
      "kind": "exemption",
      "meaning": "A person who holds a flight instructor certificate need not accomplish the one hour of ground training specified in paragraph (a) of § 61.56 if that person has, since the beginning of the 24th calendar month before the month in which that pilot acts as pilot in command, satisfactorily completed the recent experience requirements for a flight instructor certificate under § 61.197."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F002", "F006", "F017"],
      "kind": "exemption",
      "meaning": "A person who holds a flight instructor certificate need not accomplish the one hour of ground training specified in paragraph (a) of § 61.56 if that person has, since the beginning of the 24th calendar month before the month in which that pilot acts as pilot in command, reinstated the person's flight instructor privileges by satisfactorily completing an approved flight instructor refresher course in accordance with § 61.199(a)(1)."
    },
    {
      "quote_ref": "F020",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "A student pilot need not accomplish the flight review required by § 61.56 provided the student pilot is undergoing training for a certificate and has a current solo flight endorsement as required under § 61.87."
    },
    {
      "quote_ref": "F021",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The flight review requirements of § 61.56 may be accomplished in combination with the requirements of § 61.57 and other applicable recent experience requirements at the discretion of the authorized instructor conducting the flight review."
    },
    {
      "quote_ref": "F023",
      "scope_refs": ["F022"],
      "kind": "condition",
      "meaning": "If a flight simulator or flight training device is used to meet the flight review requirements of § 61.56, it must be used in accordance with an approved course conducted by a training center certificated under 14 CFR part 142."
    },
    {
      "quote_ref": "F024",
      "scope_refs": ["F022"],
      "kind": "condition",
      "meaning": "If a flight simulator or flight training device is used to meet the flight review requirements of § 61.56, the applicant must meet the takeoff and landing requirements of § 61.57(a) or § 61.57(b), unless the flight review is undertaken in a flight simulator that is approved for landings."
    },
    {
      "quote_ref": "F025",
      "scope_refs": ["F022"],
      "kind": "condition",
      "meaning": "If a flight simulator or flight training device is used to meet the flight review requirements of § 61.56, it must represent an aircraft or set of aircraft for which the pilot is rated."
    },
    {
      "quote_ref": "F026",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Docket numbers, Federal Register citations, and amendment history for § 61.56 containing no substantive pilot standards or duties."
    }
  ]
}
